import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"横渠易说 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"横渠易说 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"zh/classics/hengqu/059.md","filePath":"zh/classics/hengqu/059.md"}'),l={name:"zh/classics/hengqu/059.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><h3 id="彖曰-重巽以申命-刚巽乎中正而志行-柔皆顺乎刚-是以小亨-利有攸往-利见大人。" tabindex="-1">彖曰：重巽以申命，刚巽乎中正而志行，柔皆顺乎刚，是以小亨，利有攸往，利见大人。 <a class="header-anchor" href="#彖曰-重巽以申命-刚巽乎中正而志行-柔皆顺乎刚-是以小亨-利有攸往-利见大人。" aria-label="Permalink to “彖曰：重巽以申命，刚巽乎中正而志行，柔皆顺乎刚，是以小亨，利有攸往，利见大人。”">​</a></h3><h3 id="象曰-随风巽-君子以申命行事。" tabindex="-1">象曰：随风巽，君子以申命行事。 <a class="header-anchor" href="#象曰-随风巽-君子以申命行事。" aria-label="Permalink to “象曰：随风巽，君子以申命行事。”">​</a></h3><h3 id="初六-进退利武人之贞。-象曰-进退-志疑也-利武人之贞-志治也。" tabindex="-1">初六，进退利武人之贞。 象曰：“进退”，志疑也；“利武人之贞”，志治也。 <a class="header-anchor" href="#初六-进退利武人之贞。-象曰-进退-志疑也-利武人之贞-志治也。" aria-label="Permalink to “初六，进退利武人之贞。 象曰：“进退”，志疑也；“利武人之贞”，志治也。”">​</a></h3><p>体柔居下，在巽之始，谦抑过中，故施于武人之贞则适得其宜。进退者，柔不自决之象也。</p><h3 id="九二-巽在床下-用史巫纷若-吉无咎。-象曰-纷若之吉-得中也。" tabindex="-1">九二，巽在床下，用史巫纷若，吉无咎。 象曰：纷若之吉，得中也。 <a class="header-anchor" href="#九二-巽在床下-用史巫纷若-吉无咎。-象曰-纷若之吉-得中也。" aria-label="Permalink to “九二，巽在床下，用史巫纷若，吉无咎。 象曰：纷若之吉，得中也。”">​</a></h3><p>以阳居阴，其志下比，无应于上，故曰“巽在床下”。然不失中道，下为之用，故史巫纷若乐为之使，吉而无咎，非如上九丧其资斧。史巫，喻虚华过实者，言不失中道，则乐尽其诚者众矣。</p><h3 id="九三-频巽-吝。-象曰-频巽之吝-志穷也。" tabindex="-1">九三，频巽，吝。 象曰：频巽之吝，志穷也。 <a class="header-anchor" href="#九三-频巽-吝。-象曰-频巽之吝-志穷也。" aria-label="Permalink to “九三，频巽，吝。 象曰：频巽之吝，志穷也。”">​</a></h3><p>三处阳刚，失巽之道，乘刚而动，频吝所宜，志在比物，故吝，如复之六三志穷也。</p><h3 id="六四-悔亡-田获三品。-象曰-田获三品-有功也。" tabindex="-1">六四，悔亡，田获三品。 象曰：“田获三品”，有功也。 <a class="header-anchor" href="#六四-悔亡-田获三品。-象曰-田获三品-有功也。" aria-label="Permalink to “六四，悔亡，田获三品。 象曰：“田获三品”，有功也。”">​</a></h3><p>柔顺之德，以阴居位，虽或乘刚，悔终可亡。近比于五，不为谄妄，而又二三并为所获，不私其累而乐为己用，田获之类也。使三阳见获，四之功也。</p><h3 id="九五-贞吉悔亡-无不利-无初有终。先庚三日-后庚三日-吉。-象曰-九五之吉-位正中也。" tabindex="-1">九五，贞吉悔亡，无不利，无初有终。先庚三日，后庚三日，吉。 象曰：九五之吉，位正中也。 <a class="header-anchor" href="#九五-贞吉悔亡-无不利-无初有终。先庚三日-后庚三日-吉。-象曰-九五之吉-位正中也。" aria-label="Permalink to “九五，贞吉悔亡，无不利，无初有终。先庚三日，后庚三日，吉。 象曰：九五之吉，位正中也。”">​</a></h3><p>解见蛊卦。志不以正，则将有悔。“先庚三日”，让始也；“后庚三日”，存终也；虽体阳居尊，无应于下，故不可为事之唱乃吉。不着于繇辞者，巽非忧患之时故也。</p><h3 id="上九-巽在床下-丧其资斧-贞凶。-象曰-巽在床下-上穷也-丧其资斧-正乎凶也。" tabindex="-1">上九，巽在床下，丧其资斧，贞凶。 象曰：“巽在床下”，上穷也；“丧其资斧”，正乎凶也。 <a class="header-anchor" href="#上九-巽在床下-丧其资斧-贞凶。-象曰-巽在床下-上穷也-丧其资斧-正乎凶也。" aria-label="Permalink to “上九，巽在床下，丧其资斧，贞凶。 象曰：“巽在床下”，上穷也；“丧其资斧”，正乎凶也。”">​</a></h3><p>柔巽过极，难为之下，物不为用，故曰“丧其资斧凶”。资斧尚丧，余用殚矣。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
